from mk import *
from lib import fbd
STRICT["on"] = True
import math
G = 6.67e-11; k = 3.44
Ms = 4 * math.pi ** 2 / (G * k * 1e-19)
pts = [(0.006, 0.02), (0.05, 0.17), (0.25, 0.86), (0.84, 2.89), (1.83, 6.3)]

def fig():
    g = Fig(620, 300, "שמאל: גרף T בריבוע כפונקציה של r בשלישית לחמישה כוכבי לכת, נקודות על קו ישר מהראשית עד בערך 1.83 ו-6.3. ימין: השמש, לוויין וכדור הארץ על קו אחד, המרחק בין הלוויין לכדור הארץ x")
    X, Y = g.graph(60, 260, 280, 220, "r³ (10³⁸ m³)", "T² (10¹⁹ s²)", xticks=[(v, f"{v:g}") for v in (0.5, 1, 1.5, 2)], yticks=[(v, str(v)) for v in range(1, 8)], xmax=2.1, ymax=7.3)
    g.plot(X, Y, [(0, 0), (1.95, 1.95 * k)])
    for a, b in pts: g.circle(X(a), Y(b), 4.5, fill="var(--d-accent, var(--d-body))")
    cy = 150; sx, ex = 420, 590; satx = 545
    g.circle(sx, cy, 16, fill="var(--d-fill)", stroke="var(--d-line)"); g.heb(sx, cy + 36, "שמש")
    g.circle(ex, cy, 8); g.heb(ex, cy + 28, "ארץ")
    g.ball(satx, cy, r=5); g.heb(satx - 6, cy - 16, "לוויין")
    g.line(sx + 18, cy, satx - 7, cy, width=1.3, dash="5 4")
    g.dim(satx, cy + 50, ex, cy + 50, "x", ext=False)
    for rr in (ex - sx, satx - sx):  # orbit arcs around the Sun
        a1, a2 = math.radians(-40), math.radians(40)
        p1 = (sx + rr * math.cos(a1), cy - rr * math.sin(a1)); p2 = (sx + rr * math.cos(a2), cy - rr * math.sin(a2))
        g.path(f"M {p1[0]:.1f},{p1[1]:.1f} A {rr} {rr} 0 0 0 {p2[0]:.1f},{p2[1]:.1f}", width=1.1, dash="4 5")
    return g

E(id="bagrut-2004-q5", year=2004, label="2004 שאלה 5", topic="gravitation", sub="grav-kepler", diff=4, fig=fig,
  stem=r"השאלה עוסקת בחוק השלישי של קפלר ובחוק הכבידה של ניוטון. הגרף מראה את $T^2$, ביחידות של $10^{19}\,\text{s}^2$, כפונקציה של $r^3$, ביחידות של $10^{38}\,\text{m}^3$, עבור חמישה כוכבי לכת. $T$ הוא זמן ההקפה של כוכב הלכת סביב השמש, ו-$r$ הוא המרחק שלו ממרכז השמש.",
  parts=[
    P("א", r"פתחו את החוק השלישי של קפלר, למסלולים מעגליים, מחוק הכבידה של ניוטון.", OPEN, ["principle", "algebra"], [
        S(r"משוואת כוחות בכיוון המרכז", r"כוח הכבידה של השמש נותן לכוכב הלכת את התאוצה אל המרכז. מציבים את המהירות לפי זמן המחזור", r"\frac{GM_S m}{r^2} = m\,\frac{4\pi^2}{T^2}\,r", eq=r"F = \frac{GMm}{r^2},\qquad a_R = \omega^2 r"),
        S(r"מסדרים", r"המסה של כוכב הלכת מצטמצמת. מה שנשאר באגף ימין זהה לכל כוכבי הלכת", r"\frac{T^2}{r^3} = \frac{4\pi^2}{GM_S}"),
    ], r"$\frac{T^2}{r^3} = \frac{4\pi^2}{GM_S}$, זהה לכל כוכבי הלכת"),
    P("ב1", r"מה השיפוע של הגרף, ביחידות $\text{s}^2/\text{m}^3$?", num(k * 1e-19, "s^2/m^3", tol=4), ["graph"], [
        S(r"נקודה על הקו", r"הקו עובר בראשית, ולכן מספיקה נקודה אחת רחוקה. מתחשבים ביחידות של הצירים", r"\frac{6.3 \times 10^{19}}{1.83 \times 10^{38}} \approx 3.44 \times 10^{-19}\,\text{s}^2/\text{m}^3"),
    ], r"$\approx 3.44 \times 10^{-19}\,\text{s}^2/\text{m}^3$", key=r"3.44×10^-19 s²/m³"),
    P("ב2", r"בעזרת השיפוע, מה מסת השמש?", num(Ms, "kg", tol=4), ["algebra"], [
        S(r"השיפוע לפי סעיף א", r"השיפוע של הגרף הוא היחס שמצאנו", r"\frac{4\pi^2}{GM_S} = 3.44 \times 10^{-19}"),
        S(r"מבודדים", r"מציבים את קבוע הכבידה", r"M_S = \frac{4\pi^2}{6.67 \times 10^{-11} \cdot 3.44 \times 10^{-19}} \approx 1.7 \times 10^{30}\,\text{kg}"),
    ], r"$\approx 1.7 \times 10^{30}\,\text{kg}$", key=r"1.7×10^30 kg"),
    P("ג", r"לוויין לתצפיות על השמש נע במסלול מעגלי סביב השמש. הוא נמצא כל הזמן על הקו שמחבר את השמש לכדור הארץ, כמו בתרשים, והמרחק שלו מכדור הארץ קבוע. גם המסלול של כדור הארץ סביב השמש מעגלי. זמן המחזור של הלוויין סביב השמש הוא שנה. כתבו את החוק השני של ניוטון לתנועת הלוויין, בעזרת רדיוס המסלול של כדור הארץ $r$, המהירות הזוויתית של כדור הארץ סביב השמש $\omega$, מסת השמש $M_S$, מסת כדור הארץ $M_E$, והמרחק $x$ בין הלוויין לכדור הארץ. אין צורך לפתור.", choice([r"$\frac{GM_S}{(r - x)^2} - \frac{GM_E}{x^2} = \omega^2 (r - x)$", r"$\frac{GM_S}{(r - x)^2} + \frac{GM_E}{x^2} = \omega^2 (r - x)$", r"$\frac{GM_S}{r^2} - \frac{GM_E}{x^2} = \omega^2 r$", r"$\frac{GM_S}{(r - x)^2} = \omega^2 (r - x)$"], 0), ["principle", "fbd"], [
        S(r"שני כוחות על הלוויין", r"השמש מושכת אותו אל המרכז. כדור הארץ, שנמצא מעבר ללוויין, מושך אותו החוצה. הכיוון החיובי אל השמש", r"\Sigma F = \frac{GM_S m}{(r - x)^2} - \frac{GM_E m}{x^2}", eq=r"F = \frac{GMm}{r^2}"),
        S(r"משוואת כוחות בכיוון המרכז", r"זמן המחזור שנה, ולכן המהירות הזוויתית כמו של כדור הארץ. רדיוס המסלול קטן יותר. המסה של הלוויין מצטמצמת", r"\frac{GM_S}{(r - x)^2} - \frac{GM_E}{x^2} = \omega^2\,(r - x)", eq=r"a_R = \omega^2 r"),
    ], r"$\frac{GM_S}{(r - x)^2} - \frac{GM_E}{x^2} = \omega^2 (r - x)$", key=r"GMS/(r−x)² − GME/x² = ω²(r−x)"),
    P("ד", r"לכדור הארץ וללוויין אותו זמן מחזור, אבל רדיוסים שונים. לכן הלוויין לא מקיים, ביחס לשמש, את החוק השלישי של קפלר. מה הסיבה הפיזיקלית?", OPEN, ["principle"], [
        S(r"החוק של קפלר מניח כוח מגוף אחד", r"החוק נכון כשרק השמש מושכת. על הלוויין פועלת גם המשיכה של כדור הארץ, והיא לא זניחה כי הלוויין קרוב אליו", r"\Sigma F \ne \frac{GM_S m}{(r - x)^2}"),
    ], r"על הלוויין פועל גם כוח הכבידה של כדור הארץ"),
  ],
  concepts=["החוק השלישי של קפלר", "שיפוע גרף", "מסת השמש", "לוויין בין השמש לכדור הארץ"],
  summary=r"פיתוח החוק השלישי של קפלר מחוק הכבידה, מסת השמש משיפוע הגרף, ולוויין על הקו שבין השמש לכדור הארץ שנמשך גם לכדור הארץ.",
  review="הנחה שלי.\nבסעיף ג התלמיד בוחר את המשוואה הנכונה מתוך ארבע.\nמה לבדוק: רק לאשר.")
